#include <cstdio>
#include <iostream>

int gcd(int a, int b) {
    if (a > b) {
        int t = a;
        a = b;
        b = t;
    }

    // Special case for zero
    if (a == 0 || b == 0) {
        return a + b;
    }

    // Calculate GCD using Euclidean algorithm
    int result = 1;

    for (;;) {
        int remain = b % a;

        if (remain == 0) {
            result *= a;
            break;
        } else {
            b = a;
            a = remain;
        }
    }
    return result;
}

int main() {
    int simon, antisimon, stones;

    scanf("%d %d %d", &simon, &antisimon, &stones);

    for (;;) {
        // Simon plays
        int simonQuota = gcd(simon, stones);

        if (simonQuota <= stones) {
            stones -= simonQuota;
        } else {
            std::cout << 1 << std::endl;
            return 0;
        }

        // Antisimon plays
        int antiQuota = gcd(antisimon, stones);

        if (antiQuota <= stones) {
            stones -= antiQuota;
        } else {
            std::cout << 0 << std::endl;
            return 0;
        }
    }
}
